    """Parse JSON response from an agent into LayerContext."""
    text = raw_text.strip()
    start = text.find("{")
    end = text.rfind("}") + 1
    data = {}
    if start >= 0 and end > start:
        try:
            data = json.loads(text[start:end])
        except json.JSONDecodeError:
            pass

    summary = data.get("summary", text[:300] if not data else "")
    constraints = data.get("constraints", [])
    if isinstance(constraints, str):
        constraints = [constraints]
    evidence = data.get("evidence", [])

    return LayerContext(
        layer=layer_name,
        summary=summary,
        constraints=constraints,
        evidence=evidence,
        raw=data,
