def build_context_from_json(json_path: str) -> ContextStack:
    """Load pre-built context stack from a JSON file."""
    import pathlib
    p = pathlib.Path(json_path)
    if not p.exists():
        return ContextStack()
    with p.open("r", encoding="utf-8") as f:
        data = json.load(f)

    stack = ContextStack()
    if "l0_global" in data:
        g = data["l0_global"]
        stack.l0_global = LayerContext(
            layer="global_macro",
            summary=g.get("summary", ""),
            constraints=g.get("constraints", []),
            raw=g.get("raw", g),
        )
    if "l1_national" in data:
        n = data["l1_national"]
        stack.l1_national = LayerContext(
            layer="national",
            summary=n.get("summary", ""),
            constraints=n.get("constraints", []),
            raw=n.get("raw", n),
        )
    for ind in data.get("l2_industries", []):
        stack.l2_industries.append(LayerContext(
            layer=ind.get("model", "unknown"),
            summary=ind.get("summary", ""),
            raw=ind.get("raw", ind),
        ))
    return stack

